SELECT 


    sn.serial_no LIKE CONCAT('%', #{q.serialNo}, '%')
    AND sn.material_id = #{q.materialId}

        AND (m.code LIKE CONCAT('%', #{q.keyword}, '%') OR m.name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND sn.warehouse_id = #{q.warehouseId}
    AND sn.batch_no = #{q.batchNo}
    AND sn.status = #{q.status}

ORDER BY sn.id DESC
